"use client"

import React, { useEffect, type ComponentType } from "react"
import { cn } from "@heroui/react"
import { PressableCard } from "@/components/blocks/cards/PressableCard"
import { type VerdictBand, verdictBandClassName } from "@/components/blocks/cards/verdict-band"

/**
 * Column count per CONTAINER width ΓÇö these are container queries, not viewport
 * breakpoints. A block cannot know where it is placed: the same grid may sit in a
 * full page column or in a 256px rail, and a viewport breakpoint gets the rail
 * case wrong every time (wide window + narrow slot = cards crushed to a sliver).
 * Steps mirror Tailwind v4's container sizes, so the key IS the class suffix.
 */
export interface GroupPressableCardColumns {
    /** Columns at the narrowest. Defaults to `1`. */
    base?: 1 | 2
    /** From a 24rem / 384px container. */
    sm?: 2 | 3 | 4
    /** From a 28rem / 448px container. */
    md?: 2 | 3 | 4
    /** From a 32rem / 512px container. */
    lg?: 2 | 3 | 4
    /** From a 36rem / 576px container. */
    xl?: 2 | 3 | 4
    /** From a 48rem / 768px container. */
    xl3?: 2 | 3 | 4
    /** From a 56rem / 896px container. */
    xl4?: 2 | 3 | 4
}

/** One pressable card inside a {@link GroupPressableCard}. */
export interface GroupPressableCardItem {
    /** Stable React key. Also fixes the item's position for the 1ΓÇôN shortcut. */
    key: string
    /** Card body ΓÇö a buildable slot composed freely by the caller (icon tiles, text, chipsΓÇª). */
    content: ComponentType
    /** Press handler. Ignored when {@link GroupPressableCardItem.href} is set. */
    onPress?: () => void
    /** Navigation target ΓÇö renders this card as an anchor. */
    href?: string
    /** Dims the card and blocks both pressing and the keyboard shortcut. */
    isDisabled?: boolean
    /** Accessible name ΓÇö needed only when {@link GroupPressableCardItem.content} carries no readable text. */
    label?: string
    /**
     * Forwarded to this card's own `className` ΓÇö for grid placement (`@lg:col-start-2`
     * to pin a lone card to the right column) and for tile-level tweaks on top of
     * the `PressableCard` surface (a tighter `rounded-xl px-3 py-2` rating tile).
     *
     * Placement classes must use the **container** variant (`@lg:`), NOT the viewport
     * one (`lg:`), and must name the SAME step at which
     * {@link GroupPressableCardProps.columns} actually reaches that column ΓÇö a
     * `col-start-2` that outruns the column count lands in an implicit,
     * content-sized track and squeezes the card to a sliver.
     */
    className?: string
    /**
     * Verdict variant: a LEFT band (`border-l-4`) marking this tile with a signal that
     * comes from DATA (`card.md` ┬º3i) ΓÇö e.g. the SM-2 recall grade's tier. The canonical
     * {@link VerdictBand} (`variant` semantic, or `color` raw-palette escape hatch), the
     * SAME shape as `SectionCard`/`SurfaceListCardItem`.
     */
    withVerdict?: VerdictBand
}

/** Props for the {@link GroupPressableCard} block. */
export interface GroupPressableCardProps {
    /** The cards, in reading order (also the 1ΓÇôN shortcut order). */
    items: Array<GroupPressableCardItem>
    /**
     * Accessible name for the whole group ΓÇö REQUIRED. Without it a screen reader
     * hears N loose buttons with nothing tying them together.
     */
    ariaLabel: string
    /** Responsive column count. Defaults to a single column. */
    columns?: GroupPressableCardColumns
    /** Gap between cards on the spacing scale. Defaults to `3`. */
    gap?: 2 | 3
    /**
     * Binds number keys `1`ΓÇô`N` to the items in order, so the group can be driven
     * without the mouse. Off by default ΓÇö only opt in where the group IS the
     * screen's primary action (e.g. a flashcard rating bar), never for an
     * incidental grid of navigation tiles that would hijack digits globally.
     */
    keyboardShortcut?: boolean
}

// Compact grid cell, not a standalone top-level card: one step down from
// `PressableCard`'s own `rounded-3xl`/`shadow-surface` default (concentric
// radius: card 24px ΓêÆ 1 step ΓåÆ 16px) and one step UP from the flat button /
// `shadow-field` input ΓÇö `GroupPressableCard` is the ONLY place this chrome
// lives; `PressableCard` used standalone (a real full-size card, e.g.
// `ConsultantCard`) keeps its own bigger default untouched.
const TILE_CHROME = "rounded-2xl shadow-field"

// Tailwind needs LITERAL class strings ΓÇö `@sm:grid-cols-${n}` interpolation is
// never emitted by the compiler, so each supported count maps to a written-out
// class. The `@` prefix = container query (Tailwind v4 core, no plugin).
/** Grid template per base column count. */
const BASE_COLUMNS_CLASS: Record<1 | 2, string> = {
    1: "grid-cols-1",
    2: "grid-cols-2",
}
/** Container-step key ΓåÆ its literal class map, applied in ascending width order. */
const STEP_COLUMNS_CLASS: Record<
    Exclude<keyof GroupPressableCardColumns, "base">,
    Record<2 | 3 | 4, string>
> = {
    sm: { 2: "@sm:grid-cols-2", 3: "@sm:grid-cols-3", 4: "@sm:grid-cols-4" },
    md: { 2: "@md:grid-cols-2", 3: "@md:grid-cols-3", 4: "@md:grid-cols-4" },
    lg: { 2: "@lg:grid-cols-2", 3: "@lg:grid-cols-3", 4: "@lg:grid-cols-4" },
    xl: { 2: "@xl:grid-cols-2", 3: "@xl:grid-cols-3", 4: "@xl:grid-cols-4" },
    xl3: { 2: "@3xl:grid-cols-2", 3: "@3xl:grid-cols-3", 4: "@3xl:grid-cols-4" },
    xl4: { 2: "@4xl:grid-cols-2", 3: "@4xl:grid-cols-3", 4: "@4xl:grid-cols-4" },
}
/** Ascending container-step order ΓÇö later steps must win, so emit them in width order. */
const STEP_ORDER = ["sm", "md", "lg", "xl", "xl3", "xl4"] as const
/** Gap class per supported spacing step. */
const GAP_CLASS: Record<2 | 3, string> = {
    2: "gap-2",
    3: "gap-3",
}

/**
 * A grid of `PressableCard`s that act and then get out of the way ΓÇö the whole
 * group is ONE labelled unit (`role="group"` + `aria-label`), each cell is a
 * canonical `PressableCard`, and the cards' bodies stay the caller's to compose.
 *
 * Exists because a bare `<div className="grid">` of cards leaves a screen reader
 * hearing N loose buttons with nothing tying them together, and because the same
 * responsive-grid + keyboard plumbing was being hand-rolled at every call site.
 *
 * Reflows on the CONTAINER's width, not the viewport's ({@link GroupPressableCardColumns}) ΓÇö
 * a reusable block does not know whether it was dropped into a full page column or
 * a 256px rail, and a viewport breakpoint reads a wide window as "I have room" even
 * when the actual slot is a sliver.
 *
 * **Not a selection control.** Nothing here stays "chosen": press a card and the
 * surface acts (grade the card, open the page) ΓÇö so these are ACTIONS, not radios.
 * When the pick must PERSIST and read back as "this is my choice", use
 * `SelectableCardGroup` instead (a real HeroUI `RadioGroup`: `value`/`onChange`,
 * accent outline on the selected card, arrow-key roving). Deliberately no
 * `selected` prop here ΓÇö that boundary is the whole point of two blocks.
 *
 * @param props - {@link GroupPressableCardProps}
 * @see Story: .storybook/stories/blocks/cards/GroupPressableCard/GroupPressableCard.stories
 */
export const GroupPressableCard = ({
    items,
    ariaLabel,
    columns = {},
    gap = 3,
    keyboardShortcut = false,
}: GroupPressableCardProps) => {
    // `items` is typically rebuilt inline by the caller (`options.map(...)`), so a
    // fresh array arrives every render. Reading it through a ref keeps the window
    // listener subscribed ONCE instead of tearing down and re-adding on each pass,
    // while the handler still sees the current items.
    const itemsRef = React.useRef(items)
    useEffect(() => {
        itemsRef.current = items
    }, [items])

    // Press 1ΓÇôN to act without reaching for the mouse. Opt-in: the listener is
    // on `window`, so a group that isn't the screen's main action would steal
    // every digit the page sees.
    useEffect(() => {
        if (!keyboardShortcut) {
            return
        }
        const onKeyDown = (event: KeyboardEvent) => {
            // never hijack a digit the user is typing into a field
            const target = event.target as HTMLElement | null
            if (target && (target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable)) {
                return
            }
            const position = Number(event.key) - 1
            const current = itemsRef.current
            if (!Number.isInteger(position) || position < 0 || position >= current.length) {
                return
            }
            const item = current[position]
            if (item.isDisabled || !item.onPress) {
                return
            }
            event.preventDefault()
            item.onPress()
        }
        window.addEventListener("keydown", onKeyDown)
        return () => window.removeEventListener("keydown", onKeyDown)
    }, [keyboardShortcut])

    // an empty group would announce a label with nothing under it
    if (items.length === 0) {
        return null
    }

    return (
        // The `@container` wrapper is NOT decorative: an element cannot query its
        // own size, so the queried grid must live inside the container it reacts to.
        <div className="@container">
            <div
                role="group"
                aria-label={ariaLabel}
                className={cn(
                    "grid",
                    GAP_CLASS[gap],
                    BASE_COLUMNS_CLASS[columns.base ?? 1],
                    STEP_ORDER.map((step) => {
                        const count = columns[step]
                        return count === undefined ? undefined : STEP_COLUMNS_CLASS[step][count]
                    }),
                )}
            >
                {items.map((item) => {
                    const Content = item.content
                    return (
                        <PressableCard
                            key={item.key}
                            onPress={item.onPress}
                            href={item.href}
                            isDisabled={item.isDisabled}
                            label={item.label}
                            className={cn(
                                TILE_CHROME,
                                // canonical verdict left-band (shape + colour + !important fix)
                                verdictBandClassName(item.withVerdict),
                                item.className,
                            )}
                        >
                            <Content />
                        </PressableCard>
                    )
                })}
            </div>
        </div>
    )
}

"use client"

import React, {
    useEffect,
} from "react"
import {
    Logo,
} from "./Logo"
import {
    AccountMenuDropdown,
} from "./AccountMenuDropdown"
import {
    NavLinks,
} from "./NavLinks"
import {
    SearchButton,
} from "./SearchButton"
import {
    NotificationBell,
} from "./NotificationBell"
import { useSearchOverlayState } from "@/hooks/zustand/overlay/hooks"

/**
 * Props for {@link Navbar}.
 */
export type NavbarProps = Record<string, never>
/**
 * Navbar ΓÇö top application navigation bar.
 *
 * Container: owns the Ctrl/Cmd+K search shortcut and renders the logo,
 * self-navigating links, search trigger, and the account dropdown.
 * `"use client"` for hooks + keyboard handling.
 * @param props - optional root class name
 */
export const Navbar = () => {
    const { open: openSearch } = useSearchOverlayState()

    // register the global Ctrl/Cmd+K shortcut to open the search overlay
    useEffect(() => {
        const onKeyDown = (event: KeyboardEvent) => {
            const isK = event.key.toLowerCase() === "k"
            if (!isK) return
            if (!(event.ctrlKey || event.metaKey)) return
            event.preventDefault()
            openSearch()
        }
        window.addEventListener("keydown", onKeyDown)
        return () => window.removeEventListener("keydown", onKeyDown)
    }, [openSearch])

    return (
        <nav className={"sticky top-0 z-50 h-16 min-h-16 border-b bg-background"}>
            <div className="mx-auto flex h-full w-full items-center justify-between px-3">
                <div className="flex items-center gap-6">
                    <Logo className="flex-1 justify-start" />
                    <NavLinks />
                </div>

                <div className="flex items-center justify-end gap-3">
                    <SearchButton />
                    <NotificationBell />
                    <AccountMenuDropdown />
                </div>
            </div>
        </nav>
    )
}

"use client"

import {
    CaretDoubleLeftIcon,
    CaretDoubleRightIcon,
} from "@phosphor-icons/react"
import React from "react"
import { useTranslations } from "next-intl"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { toggleRightCollapsed } from "@/redux/slices/sidebar"

/** Props for {@link LearnPanelToggles}. */
export type LearnPanelTogglesProps = Record<string, never>
/**
 * Desktop collapse handle styled as a short accent bar on the content's right
 * border.
 *
 * Container: reads/dispatches the right-rail collapse flag on the `sidebar` slice.
 * The handle (right border) shrinks/expands the module-outline rail. (The LEFT
 * rail now collapses via the {@link import("@/components/blocks").CollapsibleSidebar}
 * block's own toggle, so no left handle is rendered here.) The handle is a slim
 * vertical bar that reveals a direction caret on hover, kept centered in the
 * viewport via a sticky wrapper. Hidden below `lg` (mobile uses drawers). Must be
 * rendered inside a `relative` content column. `"use client"` for redux + presses.
 * @param props - {@link LearnPanelTogglesProps}
 */
export const LearnPanelToggles = () => {
    const t = useTranslations()
    const dispatch = useAppDispatch()
    // current collapse state drives both the caret direction and the aria label
    const rightCollapsed = useAppSelector((state) => state.sidebar.rightCollapsed)

    // short vertical bar that grows a touch on hover
    const barClass = "block h-16 w-1.5 rounded-full bg-accent/60 transition-all duration-200 group-hover:h-24 group-hover:bg-accent"
    // hover caret chip centered on the bar
    const caretClass = "absolute left-1/2 top-1/2 flex size-5 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full bg-accent text-white opacity-0 shadow transition-opacity duration-200 group-hover:opacity-100"

    return (
        // full-height, click-through overlay spanning the content column; desktop only.
        // absolute so it adds no layout, z-20 to float above the article text.
        <div className={"pointer-events-none absolute inset-0 z-20 hidden @app-lg:block"}>
            {/* zero-height bar that sticks at viewport mid-line, so the handle stays centered while scrolling */}
            <div className="sticky top-1/2">
                {/* right handle: sits on the divider between content and the outline rail */}
                <button
                    type="button"
                    aria-label={rightCollapsed ? t("nav.expandRightRail") : t("nav.collapseRightRail")}
                    title={rightCollapsed ? t("nav.expandRightRail") : t("nav.collapseRightRail")}
                    onClick={() => dispatch(toggleRightCollapsed())}
                    className="group pointer-events-auto absolute right-0 top-1/2 -translate-y-1/2 translate-x-1/2 cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 rounded-full"
                >
                    <span className={barClass} />
                    {/* caret points outward (collapse) when expanded, inward (expand) when collapsed */}
                    <span className={caretClass}>
                        {rightCollapsed ? (
                            <CaretDoubleLeftIcon className="size-3" />
                        ) : (
                            <CaretDoubleRightIcon className="size-3" />
                        )}
                    </span>
                </button>
            </div>
        </div>
    )
}

"use client"

import React from "react"
import {
    Label,
    Link,
    ScrollShadow,
    cn,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useTableOfContents,
} from "./hooks/useTableOfContents"
import {
    LessonFlashcards,
} from "./LessonFlashcards"
import {
    LessonChallenges,
} from "./LessonChallenges"
import {
    ContentActions,
} from "./ContentActions"
import { useAppSelector } from "@/redux/hooks"
import { ContentTab } from "@/redux/slices/tabs"

/** Props for {@link OnThisPage}. */
export interface OnThisPageProps {
    /**
     * Render as a full-width mobile panel (the bottom-tab "On this page" view):
     * drops the hidden/sticky/width rail chrome and keeps just the body. Default
     * `false` = the desktop right rail.
     */
    mobile?: boolean
}

/**
 * "On this page" rail ΓÇö the docs-style right outline of the lesson currently
 * being read: the in-article headings with anchor-jump + scroll-spy.
 *
 * Container: reads the active lesson id from Redux (re-scan key) and derives its
 * outline from the rendered article via {@link useTableOfContents}. Self-sizing ΓÇö
 * renders nothing when the active body has no headings (module overview, code /
 * sandbox tabs, short lessons), so the content reclaims the full width.
 *
 * @param props - {@link OnThisPageProps}
 */
export const OnThisPage = ({ mobile = false }: OnThisPageProps) => {
    const t = useTranslations()
    const contentId = useAppSelector((state) => state.content.id)
    const contentTab = useAppSelector((state) => state.tabs.contentTab)
    const { headings, activeId, onJump } = useTableOfContents(contentId)

    // The rail is the per-lesson sidebar (outline + actions + review + practice), so it shows
    // whenever a lesson is open ΓÇö NOT only when the body has headings. Earlier it self-hid on
    // `headings.length === 0`, which wrongly dropped the WHOLE rail (incl. actions/review/practice)
    // on the Challenges tab (a card list with no headings) ΓåÆ the layout jumped. Now we hide only
    // when no lesson is open (e.g. module overview) so there is nothing to host.
    if (!contentId) {
        return null
    }

    // shared body: the outline + the per-lesson action/review/practice blocks
    const body = (
        <>
            {/* in-article outline ΓÇö only when the active body has headings (the prose Content
                tab). The Challenges tab body is a card list with none, so the outline is omitted
                while the rest of the rail stays put. */}
            {headings.length > 0 && (
                <nav className="flex flex-col gap-3">
                    <Label>{t("onThisPage.title")}</Label>
                    <div className="flex flex-col gap-2">
                        {headings.map((heading) => (
                            <Link
                                key={heading.id}
                                onPress={() => onJump(heading.id)}
                                className={cn("cursor-pointer text-start",
                                    heading.level >= 3 && "pl-3",
                                    heading.id === activeId ? "text-accent-soft-foreground" : "text-muted",
                                )}
                            >
                                {heading.text}
                            </Link>
                        ))}
                    </div>
                </nav>
            )}

            {/* content actions (bookmark / share / fullscreen) ΓÇö moved from the inline bar */}
            <ContentActions />

            {/* "review this lesson" ΓÇö flashcard decks linked to this content */}
            <LessonFlashcards />

            {/* "practice this lesson" ΓÇö challenges of this content (closes the loop). Hidden ON
                the Challenges tab, where the body already lists them (avoid the duplicate). */}
            {contentTab !== ContentTab.Challenges && <LessonChallenges />}
        </>
    )

    // mobile bottom-tab "On this page" view: full-width panel, no rail chrome
    if (mobile) {
        return <div className={"flex flex-col gap-6 p-6"}>{body}</div>
    }

    return (
        <aside
            className={cn(
                "hidden w-64 shrink-0 @app-lg:ml-8 @app-lg:block @app-lg:sticky @app-lg:top-16 @app-lg:self-start @app-lg:max-h-[calc(100dvh-4rem)]")}
        >
            {/* ScrollShadow owns the overflow + fades the top/bottom edges so a long
                outline reads as scrollable (the rail often overflows the viewport). */}
            <ScrollShadow hideScrollBar className="@app-lg:max-h-[calc(100dvh-4rem)] @app-lg:overflow-y-auto">
                <div className="flex flex-col gap-6 p-6 pl-0">{body}</div>
            </ScrollShadow>
        </aside>
    )
}

export default OnThisPage

"use client"

import React, {
    useCallback,
    useEffect,
    useRef,
    useState,
} from "react"
import useSWR from "swr"
import useSWRInfinite from "swr/infinite"
import { useLocale } from "next-intl"
import { useAppSelector } from "@/redux/hooks"
import { Discussion } from "@/components/blocks/community/Discussion"
import { GraphQLHeadersKey, type GraphQLHeaders } from "@/modules/api/graphql/types"
import { mutateCreateComment } from "@/modules/api/graphql/mutations/mutation-create-comment"
import { mutateDeleteComment } from "@/modules/api/graphql/mutations/mutation-delete-comment"
import { mutateReactToComment } from "@/modules/api/graphql/mutations/mutation-react-to-comment"
import { mutateUpdateComment } from "@/modules/api/graphql/mutations/mutation-update-comment"
import { queryContentComments } from "@/modules/api/graphql/queries/query-content-comments"
import { queryContentReactions } from "@/modules/api/graphql/queries/query-content-reactions"
import { ReactionType, type CommentNode } from "@/modules/api/graphql/queries/types/discussion"
import { contentDiscussionSocketIoEventEmitter } from "@/hooks/socketio/useContentDiscussionSocketIoLifecycle"
import { PublicationEvent } from "@/hooks/socketio/enums/publication-event"
import { SubscriptionEvent } from "@/hooks/socketio/enums/subscription-event"
import { useContentDiscussionSocketIo } from "@/hooks/socketio/useContentDiscussionSocketIo"
import { type SubscribeContentDiscussionSocketIoPayload } from "@/hooks/socketio/types/content-discussion"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Page size for a parent's replies (loaded in one shot per parent). */
const REPLIES_LIMIT = 50

/** Page size for the paginated top-level comment list ("load more"). */
const COMMENTS_PAGE_SIZE = 10

/** Server ΓåÆ client discussion events this container reacts to (revalidate on any). */
const DISCUSSION_EVENTS: ReadonlyArray<SubscriptionEvent> = [
    SubscriptionEvent.CommentCreated,
    SubscriptionEvent.CommentUpdated,
    SubscriptionEvent.CommentDeleted,
    SubscriptionEvent.ContentReactionChanged,
    SubscriptionEvent.CommentReactionChanged,
]

/**
 * Container for the lesson-content threaded comments.
 *
 * Owns the comment data hooks (local SWR), the realtime socket subscription (for BOTH
 * comment and reaction events), and all comment persistence callbacks; renders the
 * presentational {@link Discussion} (comments only ΓÇö frameless). Rendered below the reading
 * card by {@link LessonReader}. The reaction picker itself lives in the reading-card footer
 * ({@link ContentReactionBar}); this container only keeps the reaction SWR alive so socket
 * events refresh that bar via the shared cache key. `"use client"` for hooks + socket.
 */
export const ContentDiscussion = ({ className }: WithClassNames<undefined>) => {
    const locale = useLocale()
    const contentId = useAppSelector((state) => state.content.entity?.id)
    const currentUser = useAppSelector((state) => state.user.user)
    const currentUserId = currentUser?.id ?? null
    // the enrolled-guard on every discussion resolver requires the X-Course-Id header
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const socket = useContentDiscussionSocketIo()

    // course header sent on every discussion call so GraphQLMustEnrolledGuard passes
    const courseHeaders: GraphQLHeaders | undefined = courseId
        ? {
            [GraphQLHeadersKey.XCourseId]: courseId,
        }
        : undefined

    // replies loaded on demand, keyed by parent comment id
    const [repliesByParent, setRepliesByParent] = useState<Record<string, Array<CommentNode>>>({})
    // track which parents have replies loaded so realtime can refresh exactly those
    const loadedParentsRef = useRef<Set<string>>(new Set())

    // content-level reaction summary ΓÇö kept here ONLY to revalidate on realtime
    // ContentReactionChanged events; the reaction bar itself ({@link ContentReactionBar},
    // rendered in the reading-card footer) holds an SWR with this SAME key, so a
    // socket-driven mutate() here refreshes the bar through the shared cache.
    const reactionsSwr = useSWR(
        contentId && courseId ? ["content-discussion-reactions", contentId] : null,
        async () => {
            const response = await queryContentReactions({
                request: {
                    contentId: contentId as string,
                },
                headers: courseHeaders,
            })
            return response.data?.contentReactions.data
        },
    )

    // top-level comments, paginated for "load more"; each page is one API call
    const commentsSwr = useSWRInfinite(
        (pageIndex, previousPageData) => {
            // need both content + course (header) before any call (else the guard 400s)
            if (!contentId || !courseId) {
                return null
            }
            // stop paginating once a page comes back empty (reached the end)
            if (previousPageData && (previousPageData.comments?.length ?? 0) === 0) {
                return null
            }
            // 1-based page in the key tuple
            return ["content-discussion-comments", contentId, pageIndex + 1] as const
        },
        async ([, , page]) => {
            const response = await queryContentComments({
                request: {
                    contentId: contentId as string,
                    page,
                    limit: COMMENTS_PAGE_SIZE,
                },
                headers: courseHeaders,
            })
            return response.data?.contentComments.data
        },
    )

    // flatten loaded pages into a single comment list; total comes from the first page
    const commentPages = commentsSwr.data ?? []
    const comments = commentPages.flatMap((page) => page?.comments ?? [])
    const total = commentPages[0]?.total ?? 0
    // more remain while we have not yet accumulated the reported total
    const hasMore = comments.length < total
    // the last requested page is still resolving
    const isLoadingMore = commentsSwr.isValidating
        && commentsSwr.data !== undefined
        && typeof commentsSwr.data[commentsSwr.size - 1] === "undefined"

    // fetch a parent's replies and cache them in state
    const loadReplies = useCallback(async (parentId: string) => {
        if (!contentId || !courseId) {
            return
        }
        const response = await queryContentComments({
            request: {
                contentId,
                parentCommentId: parentId,
                limit: REPLIES_LIMIT,
            },
            headers: courseHeaders,
        })
        const replies = response.data?.contentComments.data?.comments ?? []
        // remember this parent so realtime updates can refresh it later
        loadedParentsRef.current.add(parentId)
        setRepliesByParent((prev) => ({
            ...prev,
            [parentId]: replies,
        }))
    }, [contentId, courseId, courseHeaders])

    // re-fetch every already-loaded reply subtree (used after a realtime event)
    const reloadLoadedReplies = useCallback(() => {
        loadedParentsRef.current.forEach((parentId) => {
            void loadReplies(parentId)
        })
    }, [loadReplies])

    // single revalidation entry point for any discussion change
    const revalidateAll = useCallback(() => {
        void reactionsSwr.mutate()
        void commentsSwr.mutate()
        reloadLoadedReplies()
    }, [reactionsSwr, commentsSwr, reloadLoadedReplies])

    // join the content's discussion room (and re-join on reconnect)
    useEffect(() => {
        if (!contentId || !courseId) {
            return
        }
        const subscribe = () => {
            const payload: SubscribeContentDiscussionSocketIoPayload = {
                data: {
                    contentId,
                },
                locale,
            }
            socket.emit(PublicationEvent.SubscribeContentDiscussion, payload)
        }
        // subscribe now if already connected, and again on every (re)connect
        if (socket.connected) {
            subscribe()
        }
        socket.on("connect", subscribe)
        return () => {
            socket.off("connect", subscribe)
        }
    }, [socket, contentId, courseId, locale])

    // refetch affected data whenever a realtime event arrives for this content
    useEffect(() => {
        if (!contentId || !courseId) {
            return
        }
        const handler = (message: { data?: { contentId?: string } }) => {
            // ignore events for other contents sharing the same socket
            if (message?.data?.contentId !== contentId) {
                return
            }
            revalidateAll()
        }
        DISCUSSION_EVENTS.forEach((event) => contentDiscussionSocketIoEventEmitter.on(event, handler))
        return () => {
            DISCUSSION_EVENTS.forEach((event) => contentDiscussionSocketIoEventEmitter.off(event, handler))
        }
    }, [contentId, courseId, revalidateAll])

    // --- persistence callbacks (optimistic-free: mutate then revalidate) ---

    const onSubmitComment = useCallback(async (body: string) => {
        if (!contentId || !courseId) {
            return
        }
        await mutateCreateComment({
            request: {
                contentId,
                body,
            },
            headers: courseHeaders,
        })
        void commentsSwr.mutate()
    }, [contentId, courseId, courseHeaders, commentsSwr])

    const onReply = useCallback(async (parentId: string, body: string) => {
        if (!contentId || !courseId) {
            return
        }
        await mutateCreateComment({
            request: {
                contentId,
                parentCommentId: parentId,
                body,
            },
            headers: courseHeaders,
        })
        // reply count + the subtree both changed
        void commentsSwr.mutate()
        void loadReplies(parentId)
    }, [contentId, courseId, courseHeaders, commentsSwr, loadReplies])

    const onEdit = useCallback(async (commentId: string, body: string) => {
        if (!courseId) {
            return
        }
        await mutateUpdateComment({
            request: {
                commentId,
                body,
            },
            headers: courseHeaders,
        })
        revalidateAll()
    }, [courseId, courseHeaders, revalidateAll])

    const onDelete = useCallback(async (commentId: string) => {
        if (!courseId) {
            return
        }
        await mutateDeleteComment({
            request: {
                commentId,
            },
            headers: courseHeaders,
        })
        revalidateAll()
    }, [courseId, courseHeaders, revalidateAll])

    const onReactComment = useCallback(async (commentId: string, type: ReactionType | null) => {
        if (!courseId) {
            return
        }
        await mutateReactToComment({
            request: {
                commentId,
                type,
            },
            headers: courseHeaders,
        })
        revalidateAll()
    }, [courseId, courseHeaders, revalidateAll])

    const onLoadReplies = useCallback((parentId: string) => {
        void loadReplies(parentId)
    }, [loadReplies])

    // hide the whole section until both content id and course id are available ΓÇö
    // course id is required by the GraphQLMustEnrolledGuard on every discussion resolver
    if (!contentId || !courseId) {
        return null
    }

    return (
        <Discussion
            className={className}
            // discussion data
            currentUserId={currentUserId}
            currentUser={currentUser ? { username: currentUser.username, avatar: currentUser.avatar } : null}
            comments={comments}
            total={total}
            isLoading={commentsSwr.isLoading}
            repliesByParent={repliesByParent}
            onSubmitComment={onSubmitComment}
            onReply={onReply}
            onEdit={onEdit}
            onDelete={onDelete}
            onReactComment={onReactComment}
            onLoadReplies={onLoadReplies}
            hasMore={hasMore}
            isLoadingMore={isLoadingMore}
            onLoadMore={() => void commentsSwr.setSize(commentsSwr.size + 1)}
        />
    )
}

/** Folder-matching alias (export-matches-folder) ΓÇö keep `ContentDiscussion` as the public name. */
export { ContentDiscussion as Discussion }

import { MagnifyingGlassPlusIcon } from "@phosphor-icons/react"
import React, { useState } from "react"
import { Modal } from "@heroui/react"

/** Props for {@link _MermaidDiagram} ΓÇö presentational; the rendered SVG already resolved. */
export interface MermaidDiagramProps {
    /** Rendered SVG markup, or `null` while the diagram is still compiling. */
    svg: string | null
    /** Translated loading text while the diagram is rendering. */
    loadingLabel: string
    /** Translated accessible label for the click-to-zoom trigger. */
    expandLabel: string
    /** Figure caption paragraph that follows the diagram (e.g. "Figure 1: ..."), if any. */
    caption?: string
    /** Translated generic caption shown when the diagram has no authored caption. */
    fallbackLabel: string
}

/**
 * Renders a mermaid diagram's already-compiled SVG, with a click-to-zoom
 * full-screen preview.
 *
 * Presentational: the connected half owns the SWR-cached `mermaid.render()`
 * call; this component only toggles the full-screen preview (`useState`,
 * UI-local) and lays the SVG out. Marked `"use client"` via the connected
 * half ΓÇö this file itself needs no browser API.
 * @param props - {@link MermaidDiagramProps}
 */
export const _MermaidDiagram = ({ svg, loadingLabel, expandLabel, caption, fallbackLabel }: MermaidDiagramProps) => {
    // Local open flag for the full-screen preview dialog (per-diagram, not a global modal).
    const [isOpen, setOpen] = useState(false)
    // Authored caption wins; otherwise show a generic figure label.
    const figureCaption = caption ?? fallbackLabel

    return (
        <figure className="rounded-xl border border-default bg-background p-3">
            {svg ? (
                <>
                    {/* Clickable inline diagram ΓÇö opens the full-screen preview on press. */}
                    <button
                        type="button"
                        aria-label={expandLabel}
                        title={expandLabel}
                        onClick={() => setOpen(true)}
                        className="group relative block w-full cursor-zoom-in"
                    >
                        {/* mermaid stamps an inline `style="max-width:Npx"` on the <svg> that
                            outranks our `max-w-full` class, so a wide diagram would otherwise push
                            the reading column past the viewport. Wrap it in an x-scroll box. */}
                        <div
                            className="overflow-x-auto [&_svg]:h-auto [&_svg]:!w-auto [&_svg]:!max-w-none"
                            dangerouslySetInnerHTML={{ __html: svg }}
                        />
                        {/* Hover affordance hinting the diagram can be enlarged. */}
                        <span className="pointer-events-none absolute right-2 top-2 rounded-medium bg-default/60 p-2 text-muted opacity-0 transition-opacity group-hover:opacity-100">
                            <MagnifyingGlassPlusIcon className="size-5" />
                        </span>
                    </button>
                    {/* Authored caption ("Figure N: ΓÇª") as a real figcaption ΓÇö the source paragraph
                        is stripped upstream so it isn't shown twice. Generic fallback stays modal-only. */}
                    {caption ? (
                        <figcaption className="mt-2 text-center text-sm italic text-muted">
                            {caption}
                        </figcaption>
                    ) : null}
                    <Modal isOpen={isOpen} onOpenChange={setOpen}>
                        <Modal.Backdrop>
                            <Modal.Container size="full">
                                <Modal.Dialog>
                                    <Modal.CloseTrigger />
                                    <Modal.Body data-principle="card-padding" className="p-4">
                                        {/* Full-screen figure: diagram scaled to fill, caption beneath. */}
                                        <figure className="flex h-full flex-col items-center justify-center gap-2">
                                            <div className="flex w-full flex-1 items-center justify-center overflow-auto">
                                                <div
                                                    className="[&_svg]:h-auto [&_svg]:w-full [&_svg]:max-w-full"
                                                    dangerouslySetInnerHTML={{ __html: svg }}
                                                />
                                            </div>
                                            <figcaption className="text-center text-sm italic text-muted">
                                                {figureCaption}
                                            </figcaption>
                                        </figure>
                                    </Modal.Body>
                                </Modal.Dialog>
                            </Modal.Container>
                        </Modal.Backdrop>
                    </Modal>
                </>
            ) : (
                <div className="text-sm text-muted">{loadingLabel}</div>
            )}
        </figure>
    )
}

