import type { ComponentType } from "react"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Container } from "@/components/frames/Container"
import { RailShell } from "@/components/frames/RailShell"
import { StackV } from "@/components/frames/Stack"
import { ProfileHero, type ProfileHeroUser } from "@/components/blocks/profile/ProfileHero"
import { ProfileTabsBar, type ProfileTab } from "@/components/blocks/navigation/ProfileTabsBar"
import { ProfileLoadingState } from "@/components/blocks/profile/ProfileLoadingState"
import { ProfileNotFoundState } from "@/components/blocks/profile/ProfileNotFoundState"
import { ProfileLockedState } from "@/components/blocks/profile/ProfileLockedState"

/**
 * `_PublicProfileLayout` ΓÇö the wrapper mounted once per `/profile/[username]/**`
 * scope. It owns the loading ΓåÆ not-found ΓåÆ locked ΓåÆ main state switch (checked in
 * that priority order); only the main branch renders the two-column shell (identity
 * aside beside the active tab's content) with the tab strip as chrome above it.
 * Body switches column-first to row at `@app-md`.
 *
 * Computes `visibleTabs`/`hiddenTabs` (from `isSelf`/`hasPublicCv`/`sectionVisibility`)
 * and `canHire` here, then hands the results down. `PublicProfileUser` extends
 * `ProfileHeroUser` with `profileLocked`, `sectionVisibility`, and `openToWork`.
 * Not-found copy is fixed; `onGoHome`/`onHire`/`onShare`/`onEditProfile`/`onGoCourses`
 * are the exits. Ported 1:1 from the storybook blueprint
 * (`.storybook/components/starci/layouts/PublicProfileLayout/PublicProfileLayout.tsx`);
 * `body` is a buildable, uncalled `ComponentType` slot (never `ReactNode`) ΓÇö the
 * connected {@link PublicProfileLayout} (`index.tsx`) supplies the active tab's route panel.
 */

/** Per-section tab visibility for a VISITOR (the owner always sees every tab) ΓÇö feeds the `visibleTabs`/`hiddenTabs` computation below. */
export interface PublicProfileSectionVisibility {
    /** Show the "Projects" tab to visitors. */
    projects: boolean
    /** Show the "Challenges" tab to visitors. */
    challenges: boolean
    /** Show the "Skills" tab to visitors. */
    skills: boolean
    /** Show the "Activity" tab to visitors. */
    activity: boolean
}

/**
 * The full profile entity this layout branches on. Extends {@link ProfileHeroUser}
 * (see file header) with the three fields only THIS layout needs.
 */
export interface PublicProfileUser extends ProfileHeroUser {
    /** `true` ΓåÆ the owner has locked the profile. Only bites a VISITOR (`profileLocked && !isSelf`). */
    profileLocked?: boolean
    /** Absent = every section tab shows. */
    sectionVisibility?: PublicProfileSectionVisibility
    /** `true` ΓåÆ this person is open to hiring offers ΓÇö half of the `canHire` gate (paired with `social.github`). */
    openToWork?: boolean
}

/** Fixed copy for the not-found branch ΓÇö see file header for why this is not a prop. */
const NOT_FOUND_TITLE = "Profile not found"
const NOT_FOUND_DESCRIPTION = "This profile does not exist, has been removed, or the link is wrong."

/** Accessible name for the tab strip ΓÇö layout-owned wording (┬º14d.1), `ProfileTabsBar` carries no i18n of its own. */
const PROFILE_TABS_ARIA_LABEL = "Public profile sections"

/** Every public-profile destination, in display order ΓÇö ported from the real `PROFILE_TABS`. */
const PROFILE_TABS: ReadonlyArray<ProfileTab> = ["overview", "projects", "challenges", "skills", "cv", "activity"]

/** The section tabs gated by {@link PublicProfileSectionVisibility} (overview + cv are never gated this way). */
const SECTION_TABS: ReadonlyArray<ProfileTab> = ["projects", "challenges", "skills", "activity"]

/**
 * Which tabs to draw for THIS viewer, and (owner-only) which of those the owner
 * switched off for everyone else ΓÇö ported from the real `ProfileTabsBar/index.tsx`'s
 * `visibleTabs`/`isSectionHidden`, now living here per the file header.
 */
const resolveProfileTabs = (
    user: PublicProfileUser,
    isSelf: boolean,
    hasPublicCv: boolean,
): { visibleTabs: ReadonlyArray<ProfileTab>, hiddenTabs: ReadonlyArray<ProfileTab> | undefined } => {
    const isSectionHidden = (tabId: ProfileTab): boolean =>
        !isSelf && SECTION_TABS.includes(tabId) && user.sectionVisibility?.[tabId as keyof PublicProfileSectionVisibility] === false
    const visibleTabs = PROFILE_TABS.filter((tabId) => {
        if (tabId === "cv") {
            return isSelf || hasPublicCv
        }
        return !isSectionHidden(tabId)
    })
    // the "┬╖ hidden" marker only makes sense for the OWNER's own view of a tab they hid from everyone else
    const hiddenTabs = isSelf
        ? SECTION_TABS.filter((tabId) => user.sectionVisibility?.[tabId as keyof PublicProfileSectionVisibility] === false)
        : undefined
    return { visibleTabs, hiddenTabs }
}

/** Props for {@link _PublicProfileLayout}. */
export interface PublicProfileLayoutProps {
    /** `true` while the profile read is still in flight (first load). */
    isLoading: boolean
    /** The resolved profile, or `null` once the read has SETTLED with nothing found. */
    user: PublicProfileUser | null
    /** `true` ΓåÆ the route's username IS the signed-in viewer. */
    isSelf: boolean
    /** `true` ΓåÆ the viewed user has a PUBLIC cv ΓÇö shows the "CV" tab to visitors too (feeds the tab-gating computation). */
    hasPublicCv: boolean
    /** Which profile tab is active right now (relayed to {@link ProfileTabsBar}). */
    activeTab: ProfileTab
    /** Fired with the tab the reader picked (relayed to {@link ProfileTabsBar}). */
    onTabChange: (tab: ProfileTab) => void
    /** `true` ΓåÆ the viewer already follows this user (relayed into {@link ProfileHero}). */
    following: boolean
    /** `true` ΓåÆ a follow/unfollow request is in flight (relayed into {@link ProfileHero}). */
    isFollowPending: boolean
    /** Fired when the follow/unfollow action is pressed (relayed into {@link ProfileHero}). */
    onToggleFollow: () => void
    /** Fired when the profile owner takes the "edit profile" action (relayed into {@link ProfileHero}'s `onEdit`). */
    onEditProfile: () => void
    /** Fired when a recruiter presses "Hire me" ΓÇö only reachable when the computed `canHire` gate is on (relayed into {@link ProfileHero}'s `onHire`). See file header. */
    onHire: () => void
    /** Fired when the share action is pressed (relayed into {@link ProfileHero}'s `onShare`). See file header. */
    onShare: () => void
    /** Fired from the not-found branch's one way out. */
    onGoHome: () => void
    /** Fired from the locked branch's one way forward (browse courses instead). */
    onGoCourses: () => void
    /**
     * The active tab's own panel ΓÇö rendered by that tab's own route. Buildable, uncalled
     * slot ΓÇö RULE 12 (never `ReactNode`). Named `body`, not `children`: React reserves
     * `children` for nested elements, so a ComponentType handed in under that name reads
     * as an element to every linter and every reader.
     */
    body: ComponentType
}

/**
 * The public-profile shell. See the file header for the four-branch switch, the
 * "registered as chrome" tab strip, and every judgement call. See
 * {@link PublicProfileLayoutProps} for the full contract.
 *
 * @param props - {@link PublicProfileLayoutProps}
 */
const _PublicProfileLayout = ({
    isLoading,
    user,
    isSelf,
    hasPublicCv,
    activeTab,
    onTabChange,
    following,
    isFollowPending,
    onToggleFollow,
    onEditProfile,
    onHire,
    onShare,
    onGoHome,
    onGoCourses,
    body,
}: PublicProfileLayoutProps) => {
    // the active tab's own panel ΓÇö an uncalled component reference (RULE 12), never a built element
    const BodySlot = body

    if (isLoading) {
        return (
            <ProfileLoadingState
                identity={{ tier: "layout", component: "PublicProfileLayout" }}
            />
        )
    }

    if (!user) {
        return (
            <ProfileNotFoundState
                title={NOT_FOUND_TITLE}
                description={NOT_FOUND_DESCRIPTION}
                onGoHome={onGoHome}
                identity={{ tier: "layout", component: "PublicProfileLayout" }}
            />
        )
    }

    // Locked profile viewed by a non-owner ΓÇö mirrors the real `isLocked = Boolean(user?.profileLocked) && !isSelf`.
    if (user.profileLocked && !isSelf) {
        return (
            <ProfileLockedState
                user={user}
                onGoCourses={onGoCourses}
                identity={{ tier: "layout", component: "PublicProfileLayout" }}
            />
        )
    }

    const { visibleTabs, hiddenTabs } = resolveProfileTabs(user, isSelf, hasPublicCv)
    // mirrors the real `PublicProfile`'s own `canHire` gate ΓÇö see file header
    const canHire = !isSelf && Boolean(user.openToWork) && Boolean(user.social?.github)

    // identity rail (ProfileHero) beside the active tab's routed panel ΓÇö RailShell owns the
    // column-first ΓåÆ row-at-@app-md switch, the fixed rail width, and the shrink strategy
    // (SettingsLayout's own outer switch uses the same frame ΓÇö see file header).
    const profileShell: ComponentTypeWithSkeleton = () => (
        <RailShell
            rail={() => (
                <ProfileHero
                    user={user}
                    isSelf={isSelf}
                    canHire={canHire}
                    following={following}
                    isFollowPending={isFollowPending}
                    onToggleFollow={onToggleFollow}
                    onHire={onHire}
                    onEdit={onEditProfile}
                    onShare={onShare}

                />
            )}
            body={() => <BodySlot />}
        />
    )

    // chrome above the body ΓÇö mirrors the real Navbar bottom-layer position; see file header
    const tabsAndBody = [
        () => (
            <ProfileTabsBar
                activeTab={activeTab}
                visibleTabs={visibleTabs}
                onTabChange={onTabChange}
                hiddenTabs={hiddenTabs}
                ariaLabel={PROFILE_TABS_ARIA_LABEL}

            />
        ),
        () => (
            <Container
                size="xl"
                padding={6}

                body={profileShell}
            />
        ),
    ]

    return (
        <StackV
            gap={1}
            identity={{ tier: "layout", component: "PublicProfileLayout" }}
            items={tabsAndBody}
        />
    )
}

export { _PublicProfileLayout }

import type {
    ArchitectureBoard,
    ArchitectureEdge,
    ArchitectureNode,
    ArchitectureSceneData,
    SceneTone,
} from "@/components/blocks/marketing/ArchitectureScene/types"
import type { HealthByName } from "../hooks/useSystemHealthPoll"
import { ARCHITECTURE_COMPONENT_MAP } from "../constants"
import { ARCHITECTURE_MODULES } from "../modules"

/**
 * Derives a scene's floor-grid bounds from its ACTUAL node cells (+ a fixed
 * margin), instead of a hardcoded `cols`/`rows` guess ΓÇö a scene builder that
 * scales node spacing by count (fan rings, chain steps) would otherwise draw a
 * grid that's too small (clipping nodes at the edge) or too big (a tiny board
 * floating in an oversized floor) for the topology it just laid out.
 *
 * @param nodes - The scene's placed nodes (post-layout).
 * @param cell - World units per cell.
 * @param margin - Extra cells of floor padding beyond the outermost node.
 */
export const boardFromNodes = (nodes: ArchitectureNode[], cell: number, margin = 2): ArchitectureBoard => {
    if (nodes.length === 0) return { cols: [-margin, margin], rows: [-margin, margin], cell }
    const xs = nodes.map((n) => n.cell[0])
    const zs = nodes.map((n) => n.cell[1])
    return {
        cols: [Math.min(...xs) - margin, Math.max(...xs) + margin],
        rows: [Math.min(...zs) - margin, Math.max(...zs) + margin],
        cell,
    }
}

/**
 * Fixed topology (integer grid cells) for the ATLAS ΓÇö one flat tier, no pods, no
 * "Core API" hub. Every element snaps to exactly ONE cell (1 node = 1 tile,
 * never overlapping ΓÇö the pod scenes' fractional coords were the "messy" part),
 * laid out in three spatial bands read topΓåÆbottom:
 *
 *  - **Applications** (rows -5,-4): the ~10 feature modules the Core API splits into
 *    (C4 ContainerΓåÆComponent) ΓÇö {@link import("../modules").ARCHITECTURE_MODULES}.
 *  - **Infrastructure** (rows -2..0): the 12 own infra components (live dot).
 *  - **External services** (col 7): the 5 external SaaS deps (live dot).
 *
 * Only infra/external cells carry a live `tone`/`status`; module cells are
 * always neutral (no health probe exists for them ΓÇö honesty).
 */
const NODE_CELLS: Record<string, [number, number]> = {
    // entry
    client: [0, -7],
    gateway: [0, -6],
    // Applications ΓÇö feature modules (2 rows ├ù 5)
    auth: [-4, -5],
    learning: [-2, -5],
    coding: [0, -5],
    ai: [2, -5],
    payment: [4, -5],
    community: [-4, -4],
    careers: [-2, -4],
    notify: [0, -4],
    ranking: [2, -4],
    media: [4, -4],
    // Infrastructure ΓÇö own infra (3 rows ├ù 4)
    postgres: [-3, -2],
    redis: [-1, -2],
    kafka: [1, -2],
    nats: [3, -2],
    minio: [-3, -1],
    qdrant: [-1, -1],
    elasticsearch: [1, -1],
    keycloak: [3, -1],
    judge0: [-3, 0],
    ollama: [-1, 0],
    mail: [1, 0],
    aiBalancer: [3, 0],
    // External services ΓÇö external SaaS, set apart on the far-right column
    github: [7, -3],
    stripe: [7, -2],
    paypal: [7, -1],
    payos: [7, 0],
    sepay: [7, 1],
}

/** The synthetic "Client" node isn't a probed backend component ΓÇö it's the
 *  page itself, always shown as reachable (this atlas IS the client). */
const CLIENT_ID = "client"
const GATEWAY_ID = "gateway"

/**
 * Structural edges: client ΓåÆ gateway (the one animated request path), gateway
 * fans into every module, and each module wires to the real infra it uses
 * (`usesInfra`). All the module/infra wiring is drawn `eventual` (faint) so it
 * recedes into structure ΓÇö until a module is selected, when {@link buildLiveScene}
 * brightens the edges that touch it ("light up the infra this module runs on").
 */
const buildAtlasEdges = (): Array<ArchitectureEdge> => {
    const edges: Array<ArchitectureEdge> = [{ from: CLIENT_ID, to: GATEWAY_ID, flow: true }]
    for (const module of ARCHITECTURE_MODULES) {
        edges.push({ from: GATEWAY_ID, to: module.id, eventual: true })
        for (const infra of module.usesInfra) {
            edges.push({ from: module.id, to: infra, eventual: true })
        }
    }
    return edges
}

const ATLAS_EDGES: Array<ArchitectureEdge> = buildAtlasEdges()

/** Maps a probed status to the map's node tone (only `normal`/`success`/`danger`
 *  tones exist ΓÇö `degraded` renders as `normal` shape + a `warning` status badge,
 *  same idea as `unknown`/"checking" rendering `normal` + an `info` badge). */
export const statusToTone = (status: string | undefined): SceneTone => {
    if (status === "up") return "success"
    if (status === "down") return "danger"
    return "normal"
}

/** Badge texts for a member node's live status line ΓÇö passed in so the builder
 *  stays a pure data function (no `useTranslations`). */
export interface MemberStatusLabels {
    checking: string
    unknown: string
    degraded: string
    down: string
}

/** Derives a member node's live `tone` + optional `status` badge from the poll,
 *  the same honest mapping the flat map uses: gray "checking" before any probe,
 *  then real up (no badge) / degraded / down / unknown. Shared by the flat scene
 *  and the pod-detail sub-scenes so both read identically. */
export const buildMemberNodeState = (
    id: string,
    healthByName: HealthByName | null,
    labels: MemberStatusLabels,
): { tone: SceneTone; status?: ArchitectureNode["status"] } => {
    const health = healthByName?.[id]
    const tone = !health ? "normal" : statusToTone(health.status)
    const status: ArchitectureNode["status"] = !healthByName
        ? { tone: "info", text: labels.checking }
        : !health
            ? { tone: "info", text: labels.unknown }
            : health.status === "degraded"
                ? { tone: "warning", text: labels.degraded }
                : health.status === "down"
                    ? { tone: "danger", text: labels.down }
                    : undefined
    return { tone, status }
}

/** i18n'd labels for the atlas scene's synthetic + module nodes + status badges. */
export interface FlatSceneLabels extends MemberStatusLabels {
    /** Client node name / sub. */
    client: string
    clientSub: string
    /** API Gateway node name / sub. */
    gateway: string
    gatewaySub: string
    /** Feature-module name / sub, by module id (`architecture.module.<id>.*`). */
    moduleName: (id: string) => string
    moduleSub: (id: string) => string | undefined
}

/** Set of module ids for O(1) "is this a neutral module node?" checks. */
const MODULE_IDS = new Set(ARCHITECTURE_MODULES.map((module) => module.id))

/**
 * Builds the live ATLAS scene: the fixed flat topology above (17 infra/external
 * + 10 feature modules on one grid, no Core hub / no pods), with each
 * infra/external node's tone/status driven by the current health poll and every
 * module node neutral (never a fake status). `healthByName === null` renders
 * every probed node as "checkingΓÇª".
 *
 * When `selectedId` names a MODULE, the edges touching it are brightened (the
 * module ΓåÆ the real infra it runs on) ΓÇö the architecture story, on demand.
 *
 * @param healthByName - Latest poll result, or `null` before the first resolve.
 * @param labels - i18n'd node names + status badge texts.
 * @param selectedId - Currently selected node id (drives edge emphasis), if any.
 */
export const buildLiveScene = (
    healthByName: HealthByName | null,
    labels: FlatSceneLabels,
    selectedId?: string,
): ArchitectureSceneData => {
    const nodes: Array<ArchitectureNode> = Object.entries(NODE_CELLS).map(([id, cell]) => {
        // the synthetic client node is this very page ΓÇö always "us", always up
        if (id === CLIENT_ID) {
            return { id, name: labels.client, sub: labels.clientSub, cell, kind: "client", tone: "success" }
        }
        // the gateway isn't an independently probed component (it's the request
        // path every OTHER probe travels through) ΓÇö tone it by whether any/all
        // probes succeeded, so a total outage still reads red.
        if (id === GATEWAY_ID) {
            const anyUp = healthByName ? Object.values(healthByName).some((c) => c.status === "up") : false
            const allDown = healthByName ? Object.values(healthByName).every((c) => c.status === "down") : false
            return {
                id,
                name: labels.gateway,
                sub: labels.gatewaySub,
                cell,
                kind: "loadBalancer",
                tone: !healthByName ? "normal" : allDown ? "danger" : anyUp ? "success" : "normal",
            }
        }
        // feature modules ΓÇö ALWAYS neutral, never a status dot (no health probe
        // exists for them; faking green would be dishonest)
        if (MODULE_IDS.has(id)) {
            return { id, name: labels.moduleName(id), sub: labels.moduleSub(id), cell, kind: "container", tone: "normal" }
        }
        // infra / external ΓÇö the live-probed nodes
        const component = ARCHITECTURE_COMPONENT_MAP[id]
        const { tone, status } = buildMemberNodeState(id, healthByName, labels)
        return {
            id,
            name: component?.name ?? id,
            sub: component?.mapSub,
            cell,
            kind: component?.kind ?? "container",
            tone,
            status,
        }
    })

    // brighten the wiring that touches the selected module (module ΓåÆ its infra +
    // gateway ΓåÆ module); everything else stays faint/structural.
    const edges = ATLAS_EDGES.map((edge) => {
        if (selectedId && (edge.from === selectedId || edge.to === selectedId)) {
            return { ...edge, eventual: false }
        }
        return edge
    })

    return {
        board: boardFromNodes(nodes, 2.4),
        // re-fit at render time to the actual bounding box (see `CameraFit`);
        // this is only the fallback viewing angle/distance before that runs.
        camera: { position: [14, 11, 12], zoom: 20 },
        nodes,
        edges,
    }
}

import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import {
    ChallengeHeader,
    type ChallengeDifficulty,
    type ChallengeStatus,
} from "@/components/blocks/learn/ChallengeHeader"
import {
    ChallengeBrief,
    type ChallengeBriefPrerequisiteItem,
    type ChallengeBriefRequirementItem,
    type ChallengeBriefStepItem,
    type ChallengeBriefOutputItem,
} from "@/components/blocks/learn/ChallengeBrief"
import {
    ChallengeDeliverableList,
    type ChallengeDeliverableItem,
} from "@/components/blocks/learn/ChallengeDeliverableList"
import { ChallengeScoreCard } from "@/components/blocks/learn/ChallengeScoreCard"
import { Container } from "@/components/frames/Container"
import { StackV } from "@/components/frames/Stack"
import { SplitWorkspace } from "@/components/frames/SplitWorkspace"

/**
 * `_ChallengePage` ΓÇö the SRC TWIN of `.storybook/components/starci/pages/
 * ChallengePage/ChallengePage.tsx`. Presentational: typed props, already
 * resolved; no fetch/store/i18n (that's the connected half, `./index.tsx`).
 *
 * A screen owns a list of
 * functions: it calls blocks, places them in frames, and hands each typed data.
 * Five functions across a read column and an act column: (1) what this
 * challenge is ΓÇö score, difficulty, the learner's status; (2) the brief; (3)
 * submit each requirement and see its graded verdict; (4) reopen grading
 * settings (chrome trigger only); (5) the roll-up score against the pass line.
 * Two columns composed with `SplitWorkspace`: a `min-w-0 flex-1` reading column
 * beside a `shrink-0 w-[360px]` sticky aside, stacked on mobile/tablet ΓåÆ
 * `@app-xl:flex-row` on desktop, inside a `Container size="xl"`. The
 * grading-settings drawer is not built ΓÇö `onOpenGradingSettings` is a chrome
 * trigger only.
 */

// re-exported so the connected file (and anything downstream) can build data
// against the SAME types the blueprint's blocks define, rather than
// redeclaring shape that already exists.
export type {
    ChallengeDifficulty,
    ChallengeStatus,
    ChallengeBriefPrerequisiteItem,
    ChallengeBriefRequirementItem,
    ChallengeBriefStepItem,
    ChallengeBriefOutputItem,
    ChallengeDeliverableItem,
}

/** Props for {@link _ChallengePage}. */
export interface ChallengePageProps {
    /** Fired when the back link is pressed. */
    onBackPress: () => void
    /** Full back-link label override; omit to fall back to the generic "Back". */
    backLabel?: string
    /** Challenge title. */
    title: string
    /** One-sentence summary of the challenge. */
    description?: string
    /** Points this challenge is worth. Omit when no score is defined yet. */
    scoreValue?: number
    /** How hard the challenge is. Always known, independent of the learner's own attempt. */
    difficulty: ChallengeDifficulty
    /** The learner's own attempt outcome. Omit when not attempted yet. */
    status?: ChallengeStatus

    /** "Before you start" lines. Section is omitted entirely when empty/absent. */
    prerequisites?: ReadonlyArray<ChallengeBriefPrerequisiteItem>
    /** Graded requirements, each collapsible with its points on the trigger. */
    requirements?: ReadonlyArray<ChallengeBriefRequirementItem>
    /** Guided steps, numbered by the brief block in order. */
    steps?: ReadonlyArray<ChallengeBriefStepItem>
    /** Expected-output lines, each with a leading check. */
    outputs?: ReadonlyArray<ChallengeBriefOutputItem>
    /** A single hint, collapsed by default. Section is omitted when blank. */
    hint?: string

    /** The challenge's requirements as live submission rows, in display order. */
    deliverables: Array<ChallengeDeliverableItem>
    /** Fired when the learner opens the grading-lane settings ΓÇö chrome trigger only this pass. */
    onOpenGradingSettings: () => void

    /** Points the learner earned across every requirement. */
    earnedScore: number
    /** Points available in total. */
    maxScore: number
    /** Fraction of `maxScore` required to pass, in the `0..1` range. */
    passThreshold: number

    /**
     * `true` ΓåÆ every block that can mirror itself does. The flag FLOWS DOWN
     * into each block rather than building a parallel skeleton tree here.
     */
    isSkeleton?: boolean
}

/**
 * The challenge solve screen. See the file header for the function list and
 * the two-column layout's known limits.
 *
 * @param props - {@link ChallengePageProps}
 */
const _ChallengePage = ({
    onBackPress,
    backLabel,
    title,
    description,
    scoreValue,
    difficulty,
    status,
    prerequisites,
    requirements,
    steps,
    outputs,
    hint,
    deliverables,
    onOpenGradingSettings,
    earnedScore,
    maxScore,
    passThreshold,
    isSkeleton = false,
}: ChallengePageProps) => {
    const readColumn = [
        () => (
            <ChallengeHeader

                onBackPress={onBackPress}
                backLabel={backLabel}
                title={title}
                description={description}
                scoreValue={scoreValue}
                difficulty={difficulty}
                status={status}
                isSkeleton={isSkeleton}

            />
        ),
        () => (
            <ChallengeBrief

                prerequisites={prerequisites}
                requirements={requirements}
                steps={steps}
                outputs={outputs}
                hint={hint}
                isSkeleton={isSkeleton}

            />
        ),
    ]

    const actColumn = [
        () => (
            <ChallengeDeliverableList

                items={deliverables}
                onOpenGradingSettings={onOpenGradingSettings}
                isSkeleton={isSkeleton}

            />
        ),
        () => (
            <ChallengeScoreCard

                earnedScore={earnedScore}
                maxScore={maxScore}
                passThreshold={passThreshold}
                isSkeleton={isSkeleton}

            />
        ),
    ]

    const challengeBody = ({ isSkeleton }: SkeletonProps) => (
        <SplitWorkspace
            isSkeleton={isSkeleton}
            main={({ isSkeleton }: SkeletonProps) => <StackV gap={7} isSkeleton={isSkeleton} items={readColumn} />}
            aside={({ isSkeleton }: SkeletonProps) => <StackV gap={6} isSkeleton={isSkeleton} items={actColumn} />}
        />
    )

    return (
        <Container
            size="xl"
            padding={6}
            isSkeleton={isSkeleton}
            body={challengeBody}
            identity={{ tier: "page", component: "ChallengePage" }}
        />
    )
}

export { _ChallengePage }

import React from "react"
import type {
    ComponentType,
    Key,
} from "react"
import {
    AdBanner,
} from "@/components/blocks/marketing/AdBanner"
import type {
    ContentTabItem,
} from "@/components/blocks/learn/lesson/types"
import {
    ContentTabBar,
