/** Props for {@link MockInterviewPage}. */
export interface MockInterviewPageProps {
    /**
     * Present when reached via the dedicated `/mock-interview/interview/[sessionId]`
     * route ΓÇö threaded straight through to {@link MockInterviewSession}, which
     * rehydrates that server-persisted session (24h TTL) instead of showing the
     * green room.
     */
    resumeSessionId?: string
    /** Present on the `/interview/[sessionId]/result` route ΓÇö shows the graded debrief. */
    resultSessionId?: string
}

/**
 * Mock-interview feature shell: gates the surface behind enrollment (it spends AI
 * credits), and frames the {@link MockInterviewSession} state machine with the
 * standard learn header + breadcrumb.
 *
 * Two shapes, stated as two composed trees rather than one conditional class
 * string: the LIVE interview and the result debrief are full-bleed work surfaces
 * that own their own header, while the green room is a centred reading column.
 *
 * DEBT: `MockInterviewSetupSkeleton` / `MockInterviewSessionSkeleton` are still
 * separate descriptions of the two surfaces below. Folding them in means giving a
 * state machine its own resting state ΓÇö a change worth reviewing on its own.
 *
 * @param props - {@link MockInterviewPageProps}
 */
export const MockInterviewPage = ({ resumeSessionId, resultSessionId }: MockInterviewPageProps) => {
    const t = useTranslations()
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    // enrollment status is only ever FETCHED while authenticated (the query's key is
    // disabled otherwise ΓÇö see `useQueryCourseEnrollmentStatusSwr`), so a guest's
    // `enrollmentSwr.data` stays `undefined` forever; without checking `authenticated`
    // below, `enrollmentResolved` would never flip and the surface would rest forever
    // instead of settling straight into the enroll gate.
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    // enrolled-only (spends AI credits) ΓÇö gate trial viewers behind an enroll CTA
    const enrollmentSwr = useQueryCourseEnrollmentStatusSwr()
    const isEnrolled = enrollmentSwr.data?.courseEnrollmentStatus?.data?.isEnrolled === true
    // during the LIVE interview phase the shell goes full-bleed (course rails dropped via
    // `?phase=interview`); drop the centred measure + page header here to match ΓÇö the
    // interview is a focused work surface, not a centred reading column. A
    // `resumeSessionId` (the dedicated `/interview/[sessionId]` route) always lands
    // straight in the interview phase, so it counts as live immediately too ΓÇö no
    // waiting on the query-param mirror to catch up after mount.
    const isLive = useSearchParams().get("phase") === "interview" || Boolean(resumeSessionId)
    // result: its own centred page (like the flashcard quiz result), NOT the full-bleed
    // live shell ΓÇö but it owns its OWN PageHeader/BackLink internally
    // (`MockInterviewResult`), so it skips this shell's generic header the same way.
    const isResult = Boolean(resultSessionId)
    // resolved once the enrollment check has actually run (nullish, not `!enrollmentSwr.data` ΓÇö
    // an `{isEnrolled: false}` payload is falsy but IS resolved) ΓÇö gates the green room /
    // live surface behind its resting state instead of rendering nothing. Guests never
    // fire the query at all, so they resolve immediately (straight to the enroll gate).
    const isSkeleton = !(!authenticated || (enrollmentSwr.data !== undefined && !enrollmentSwr.isLoading))
    const ownsItsHeader = isLive || isResult

    const surface = () => {
        if (isSkeleton) {
            return ownsItsHeader ? <MockInterviewSessionSkeleton /> : <MockInterviewSetupSkeleton />
        }
        if (!isEnrolled) {
            return (
                <EnrollGate
                    title={t("mockInterview.gateTitle")}
                    description={t("mockInterview.gateDescription")}
                    preview={<MockInterviewGatePreview />}
                />
            )
        }
        if (!(courseId && courseDisplayId)) {
            return null
        }
        return resultSessionId ? (
            <MockInterviewResult
                key={courseId}
                sessionId={resultSessionId}
                courseId={courseId}
                courseDisplayId={courseDisplayId}
            />
        ) : (
            <MockInterviewSession
                key={courseId}
                courseId={courseId}
                courseDisplayId={courseDisplayId}
                resumeSessionId={resumeSessionId}
            />
        )
    }

    // full-bleed: the surface below owns its own header and measure
    if (ownsItsHeader) {
        return (
            <StackV
                identity={{ tier: "block", component: "MockInterviewPage" }}
                gap={1}
                body={surface}
            />
        )
    }

    return (
        <Container
            identity={{ tier: "block", component: "MockInterviewPage" }}
            size="md"
            body={() => (
                <StackV
                    gap={7}
                    items={[
                        () => (
                            <PageHeader
                                breadcrumb={<LearnBreadcrumb current={t("mockInterview.title")} />}
                                title={t("mockInterview.title")}
                                description={t("mockInterview.subtitle")}
                            />
                        ),
                        surface,
                    ]}
                />
            )}
        />
    )
}

import React from "react"
import { StackIcon } from "@phosphor-icons/react"
import { ModuleHeader, type ModuleHeaderCrumb } from "@/components/blocks/learn/ModuleHeader"
import { ModuleContinueBand } from "@/components/blocks/learn/ModuleContinueBand"
import { ModuleLessonList, type ModuleLessonListLesson } from "@/components/blocks/learn/ModuleLessonList"
import { ModuleChallengeList, type ModuleChallengeItem } from "@/components/blocks/learn/ModuleChallengeList"
import { ContentPaywall } from "@/components/blocks/learn/ContentPaywall"
import type { PricingPhase } from "@/modules/types/enums/pricing-phase"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Container } from "@/components/frames/Container"
import { StackV } from "@/components/frames/Stack"
import type { CourseContentTier } from "@/modules/types/enums/course-content-tier"
import type { CallerIdentity } from "@/components/frames/_identity"

/** This page's own identity ΓÇö handed to whichever frame is standing in as its root (`_identity.ts`). */
const PAGE_IDENTITY: CallerIdentity = { tier: "page", component: "ModulePage" }

/**
 * `_ModulePage` ΓÇö the SRC TWIN of `.storybook/components/starci/pages/
 * ModulePage/ModulePage.tsx`. Presentational: typed props, already resolved;
 * no fetch/store/i18n (that's the connected half, `./index.tsx`).
 *
 * A screen owns a list of functions: it calls blocks, places them in frames,
 * and hands each typed data. Five functions in reading order ΓÇö orient
 * (`ModuleHeader`) ┬╖ gate (`ContentPaywall`, reused from the lesson reader) ┬╖
 * resume + completion (`ModuleContinueBand`) ┬╖ browse lessons
 * (`ModuleLessonList`) ┬╖ browse challenges (`ModuleChallengeList`). The
 * paywall REPLACES browsing rather than sitting above it. The challenge list
 * is a screen-owned structural switch: a module with no challenges yet does
 * not earn an empty challenge list on its own page.
 *
 * On top of the pure blueprint composition, this presentational file also
 * carries the real async lifecycle (error ΓåÆ skeleton ΓåÆ empty ΓåÆ content) ΓÇö
 * the same extension `_CourseContents` already makes, since a static
 * storybook blueprint has no fetch to fail but a real page does.
 */

/** Props for {@link _ModulePage}. */
export interface ModulePageProps {
    // ΓöÇΓöÇ async lifecycle ΓÇö owned by the connected file, not the blueprint ΓöÇΓöÇΓöÇΓöÇ
    /** `true` while the module/outline fetch is running (no cache yet). */
    isLoading?: boolean
    /** Set once loading finishes with no result ΓåÆ the error branch. */
    error?: unknown
    /** Retry the failed fetch. */
    onRetry?: () => void
    /** `true` (after loading) ΓåÆ the module has no lessons yet. */
    isEmpty?: boolean
    /** Empty-state title. */
    emptyTitle: string
    /** Error-state title. */
    errorTitle: string
    /** Error-state retry button label. */
    retryLabel: string

    // ΓöÇΓöÇ 1. orient ΓÇö `ModuleHeader` ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    /** Breadcrumb trail as data ΓÇö a module is always reached through its course. */
    breadcrumbItems: Array<ModuleHeaderCrumb>
    /** Module title. */
    title: string
    /** One-sentence summary of the module. */
    description?: string
    /** Learning tier of the module. */
    tier?: CourseContentTier
    /** How many lessons the module has, in total. */
    lessonCount?: number
    /** Total reading/study minutes across the module. */
    minutesTotal?: number
    /** How many challenges hang off the module, in total. */
    challengeCount?: number

    // ΓöÇΓöÇ whole-screen gate ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    /** `true` ΓåÆ the learner has not bought the course; the gate replaces browsing. */
    isLocked?: boolean

    // ΓöÇΓöÇ 2. gate ΓÇö `ContentPaywall` (only while `isLocked`) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    /** Paywall headline. */
    paywallTitle?: string
    /** Paywall one-sentence description of what buying unlocks. */
    paywallDescription?: string
    /** Price after discount, in VND. */
    discountedPriceVnd?: number
    /** Price before discount, for the struck-through original. */
    originalPriceVnd?: number | null
    /** Which pricing phase the course is in ΓÇö drives the scarcity line. */
    currentPhase?: PricingPhase
    /** Seats left in the current phase. `null` ΓåÆ the phase is not capped. */
    seatsRemaining?: number | null
    /** What the next phase will cost. */
    nextPhasePriceVnd?: number | null
    /** Label of the paywall's single call to action. */
    paywallCtaLabel?: string
    /** Fired when the learner takes the paywall offer. */
    onPurchase?: () => void

    // ΓöÇΓöÇ 3. resume + completion ΓÇö `ModuleContinueBand` ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    /** Title of the next unread lesson. `undefined` ΓåÆ every lesson is already read. */
    resumeLessonTitle?: string
    /** Lessons already read / total lessons in the module. */
    lessonsRead?: number
    lessonsTotal?: number
    /** Challenges already completed / total challenges in the module. */
    challengesDone?: number
    challengesTotal?: number
    /** Press "Continue learning". */
    onResume?: () => void

    // ΓöÇΓöÇ 4. browse lessons ΓÇö `ModuleLessonList` ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    /** Every lesson in the module, in reading order. */
    lessons: Array<ModuleLessonListLesson>
    /** The lesson to mark "resume" on the list. */
    resumeLessonId?: string
    /** Fired with the lesson id on any row press, premium or not. */
    onSelectLesson: (id: string) => void

    // ΓöÇΓöÇ 5. browse challenges ΓÇö `ModuleChallengeList` ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    /** Every challenge across this module's lessons, flattened. Empty ΓåÆ the block does not render at all. */
    challenges: Array<ModuleChallengeItem>
    /** Fired with the owning lesson's id. */
    onSelectChallenge: (lessonId: string) => void
}

/**
 * A module's own page. See the file header for the full function list and the
 * paywall's replace-not-stack behaviour.
 *
 * @param props - {@link ModulePageProps}
 */
export const _ModulePage = ({
    isLoading = false,
    error,
    onRetry,
    isEmpty = false,
    emptyTitle,
    errorTitle,
    retryLabel,
    breadcrumbItems,
    title,
    description,
    tier,
    lessonCount,
    minutesTotal,
    challengeCount,
    isLocked = false,
    paywallTitle,
    paywallDescription,
    discountedPriceVnd,
    originalPriceVnd,
    currentPhase,
    seatsRemaining,
    nextPhasePriceVnd,
    paywallCtaLabel,
    onPurchase,
    resumeLessonTitle,
    lessonsRead = 0,
    lessonsTotal = 0,
    challengesDone = 0,
    challengesTotal = 0,
    onResume,
    lessons,
    resumeLessonId,
    onSelectLesson,
    challenges,
    onSelectChallenge,
}: ModulePageProps) => {
    // ONE tree ΓÇö the resting state is this SAME spine with `isSkeleton` threaded into every
    // shimmer-capable block, never a hand-mirrored copy (mirrors `_CourseContents`).
    const spine = (isSkeleton: boolean) => (
        <Container
            size="md"
            padding={6}
            identity={PAGE_IDENTITY}
            body={() => (
                <StackV
                    gap={7}
                    items={[
                        () => (
                            <ModuleHeader
                                breadcrumbItems={breadcrumbItems}
                                title={title}
                                description={description}
                                tier={tier}
                                lessonCount={lessonCount}
                                minutesTotal={minutesTotal}
                                challengeCount={challengeCount}
                                isSkeleton={isSkeleton}
                            />
                        ),
                        () => (isLocked ? (
                            <ContentPaywall
                                title={paywallTitle ?? ""}
                                description={paywallDescription}
                                discountedPriceVnd={discountedPriceVnd ?? 0}
                                originalPriceVnd={originalPriceVnd}
                                currentPhase={currentPhase}
                                seatsRemaining={seatsRemaining}
                                nextPhasePriceVnd={nextPhasePriceVnd}
                                ctaLabel={paywallCtaLabel ?? ""}
                                onPurchase={onPurchase ?? (() => {})}
                                isSkeleton={isSkeleton}
                            />
                        ) : (
                            <StackV
                                gap={6}
                                isSkeleton={isSkeleton}
                                items={[
                                    () => (
                                        <ModuleContinueBand
                                            resumeLessonTitle={resumeLessonTitle}
                                            lessonsRead={lessonsRead}
                                            lessonsTotal={lessonsTotal}
                                            challengesDone={challengesDone}
                                            challengesTotal={challengesTotal}
                                            onResume={onResume}
                                            isSkeleton={isSkeleton}
                                        />
                                    ),
                                    () => (
                                        <ModuleLessonList
                                            lessons={lessons}
                                            resumeLessonId={resumeLessonId}
                                            onSelectLesson={onSelectLesson}
                                            isSkeleton={isSkeleton}
                                        />
                                    ),
                                    // A count of zero is not news (`ModuleHeader`/`ContentModeNav` idiom) ΓÇö
                                    // extended here to a whole block's presence: a module with no challenges
                                    // yet does not earn an empty challenge list on its own page.
                                    ...((isSkeleton || challenges.length > 0) ? [() => (
                                        <ModuleChallengeList
                                            challenges={challenges}
                                            onSelectChallenge={onSelectChallenge}
                                            isSkeleton={isSkeleton}
                                        />
                                    )] : []),
                                ]}
                            />
                        )),
                    ]}
                />
            )}
        />
    )

    // error ΓåÆ skeleton ΓåÆ empty ΓåÆ content (BLOCK-8): the empty and error surfaces are the shared
    // `AsyncContent*` frames dropped in as their own states; otherwise the ONE spine renders, with
    // `isLoading` flowing in as the co-located shimmer flag (loading-and-skeleton.md ┬º6).
    const inner = error
        ? <AsyncContentError title={errorTitle} onRetry={onRetry} retryLabel={retryLabel} />
        : (!isLoading && isEmpty)
            ? <AsyncContentEmpty title={emptyTitle} icon={StackIcon} />
            : spine(isLoading)

    return inner
}
